// ---- shared helpers (same block in every multi-tab Code node) ----
const noAcc = (s) => String(s ?? '').normalize('NFC').replace(/đ/g, 'd').replace(/Đ/g, 'D')
  .normalize('NFD').replace(/[̀-ͯ]/g, '').normalize('NFC');
const low = (s) => noAcc(s).toLowerCase().trim();
const truthy = (v) => v === true || ['TRUE', 'CO', 'X', '1'].includes(noAcc(v).trim().toUpperCase());
const TAB_CODES = { 'thuc don': 'td', 'thong bao': 'tb', 'lich/tkb': 'lich', 'lich': 'lich', 'tin hoat dong': 'tin' };
const TAB_EMOJI = { td: '🍽️', tb: '📢', lich: '📅', tin: '🌟' };
const tabCode = (tab) => TAB_CODES[low(tab)] || low(tab).replace(/[^a-z0-9]+/g, '');
const parseTabs = (v) => String(v || 'Thực đơn').split(',').map((t) => t.trim()).filter(Boolean);
const colLetter = (i) => { let s = ''; for (let n = i + 1; n > 0; n = Math.floor((n - 1) / 26)) s = String.fromCharCode(65 + ((n - 1) % 26)) + s; return s; };
const qTab = (tab) => `'${String(tab).replace(/'/g, "''")}'`;
const batchQuery = (tabs) => tabs.map((t) => 'ranges=' + encodeURIComponent(`${qTab(t)}!A1:Z`)).join('&');
// valueRange -> { cols: {header: letter}, rows: [{...header: value, row_number}] }
const readTab = (vr) => {
  const values = (vr && vr.values) || [];
  const header = (values[0] || []).map((h) => String(h ?? '').trim());
  const cols = {};
  header.forEach((h, i) => { if (h) cols[h] = colLetter(i); });
  const rows = values.slice(1).map((r, i) => {
    const o = { row_number: i + 2 };
    header.forEach((h, j) => { if (h) o[h] = r[j] ?? ''; });
    return o;
  });
  return { cols, rows };
};
const cell = (tab, cols, header, row) => {
  if (!cols[header]) throw new Error(`Tab "${tab}" thiếu cột "${header}"`);
  return `${qTab(tab)}!${cols[header]}${row}`;
};
const PHONE = /(?:\+?84|0)(?:\d[\s.-]?){8,10}\d/;
const nowVN = () => new Date().toLocaleString('en-GB', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false }).replace(',', '');
const todayVN = () => new Date().toLocaleDateString('en-GB', { timeZone: 'Asia/Ho_Chi_Minh' });
// ---- end shared helpers ----

const cfg = {};
for (const item of $input.all()) {
  const key = item.json['Key'] ?? item.json['Khoá'] ?? item.json['Khóa'];
  if (key === undefined || key === null || String(key).trim() === '') continue;
  const value = item.json['Value'] ?? item.json['Giá trị'] ?? '';
  cfg[String(key).trim()] = typeof value === 'string' ? value.trim() : value;
}

const missing = ['SCHOOL_NAME'].filter((k) => !String(cfg[k] ?? '').trim());
if (missing.length) throw new Error('Config tab thiếu khoá: ' + missing.join(', '));
cfg.CONTENT_TABS = parseTabs(cfg.CONTENT_TABS).join(', ');
cfg.HASHTAGS = String(cfg.HASHTAGS || '');
cfg.OLLAMA_MODEL = String(cfg.OLLAMA_MODEL || 'qwen3.5:9b');
cfg.OLLAMA_CLOUD_MODEL = String(cfg.OLLAMA_CLOUD_MODEL || 'gemma4:cloud');
cfg.GEMINI_MODEL = String(cfg.GEMINI_MODEL || 'gemini-3.8-flash').replace(/^models\//, '');
cfg.DRAFT_BATCH_LIMIT = Math.max(1, Number(cfg.DRAFT_BATCH_LIMIT) || 3);
cfg.batch_query = batchQuery(parseTabs(cfg.CONTENT_TABS));
return [{ json: cfg }];

// ---- shared helpers (same block in every multi-tab Code node) ----
const noAcc = (s) => String(s ?? '').normalize('NFC').replace(/đ/g, 'd').replace(/Đ/g, 'D')
  .normalize('NFD').replace(/[̀-ͯ]/g, '').normalize('NFC');
const low = (s) => noAcc(s).toLowerCase().trim();
const truthy = (v) => v === true || ['TRUE', 'CO', 'X', '1'].includes(noAcc(v).trim().toUpperCase());
const TAB_CODES = { 'thuc don': 'td', 'thong bao': 'tb', 'lich/tkb': 'lich', 'lich': 'lich', 'tin hoat dong': 'tin' };
const TAB_EMOJI = { td: '🍽️', tb: '📢', lich: '📅', tin: '🌟' };
const tabCode = (tab) => TAB_CODES[low(tab)] || low(tab).replace(/[^a-z0-9]+/g, '');
const parseTabs = (v) => String(v || 'Thực đơn').split(',').map((t) => t.trim()).filter(Boolean);
const colLetter = (i) => { let s = ''; for (let n = i + 1; n > 0; n = Math.floor((n - 1) / 26)) s = String.fromCharCode(65 + ((n - 1) % 26)) + s; return s; };
const qTab = (tab) => `'${String(tab).replace(/'/g, "''")}'`;
const batchQuery = (tabs) => tabs.map((t) => 'ranges=' + encodeURIComponent(`${qTab(t)}!A1:Z`)).join('&');
// valueRange -> { cols: {header: letter}, rows: [{...header: value, row_number}] }
const readTab = (vr) => {
  const values = (vr && vr.values) || [];
  const header = (values[0] || []).map((h) => String(h ?? '').trim());
  const cols = {};
  header.forEach((h, i) => { if (h) cols[h] = colLetter(i); });
  const rows = values.slice(1).map((r, i) => {
    const o = { row_number: i + 2 };
    header.forEach((h, j) => { if (h) o[h] = r[j] ?? ''; });
    return o;
  });
  return { cols, rows };
};
const cell = (tab, cols, header, row) => {
  if (!cols[header]) throw new Error(`Tab "${tab}" thiếu cột "${header}"`);
  return `${qTab(tab)}!${cols[header]}${row}`;
};
const PHONE = /(?:\+?84|0)(?:\d[\s.-]?){8,10}\d/;
const nowVN = () => new Date().toLocaleString('en-GB', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false }).replace(',', '');
const todayVN = () => new Date().toLocaleDateString('en-GB', { timeZone: 'Asia/Ho_Chi_Minh' });
// ---- end shared helpers ----

// Rows that need drafts across every content tab. Never touches a row whose website draft
// already has text (a person's edits win), nor anything already published.
const cfg = $('Read Config').first().json;
const tabs = parseTabs(cfg.CONTENT_TABS);
const ranges = ($input.first().json.valueRanges) || [];
const out = [];
tabs.forEach((tab, t) => {
  const { cols, rows } = readTab(ranges[t]);
  for (const r of rows) {
    if (!String(r['Ngày'] ?? '').trim() || !String(r['Nội dung'] ?? '').trim()) continue;
    if (String(r['Bản website'] ?? '').trim() || truthy(r['Đã đăng'])) continue;
    if (String(r['Ghi chú'] ?? '').includes('nhập tay') || String(r['Ghi chú'] ?? '').includes('Có số điện thoại')) continue;
    const code = tabCode(tab);
    out.push({ json: {
      tab, code, emoji: TAB_EMOJI[code] || '📌', row_number: r.row_number,
      ngay: String(r['Ngày']), noi_dung: String(r['Nội dung']).slice(0, 4000), nguoi_nhap: String(r['Người nhập'] ?? ''),
      phone: PHONE.test(String(r['Nội dung'])),
      cell_web: cell(tab, cols, 'Bản website', r.row_number), cell_zalo: cell(tab, cols, 'Bản Zalo', r.row_number),
      cell_fb: cell(tab, cols, 'Bản Facebook', r.row_number), cell_note: cell(tab, cols, 'Ghi chú', r.row_number),
    } });
  }
});
// One GPU: draft a few rows per run, oldest first; the rest follow on the next runs.
return out.slice(0, Number(cfg.DRAFT_BATCH_LIMIT) || 3);

// Hard rule 4: content with a phone number is not sent to any model.
const data = $input.all().map(({ json: r }) => ({ range: r.cell_note, values: [['Có số điện thoại trong nội dung - không soạn tự động. Xoá thông tin cá nhân rồi xoá ghi chú này để soạn lại, hoặc nhập tay.']] }));
return data.length ? [{ json: { data } }] : [];

