// Parse the model output into the three drafts. Items arrive from the Ollama agent, the Gemini
// agent, or Gemini's error output (both models failed) - the last ones become a visible note.
const src = (i) => { try { return $('Chọn hàng cần soạn').itemMatching(i).json; } catch (e) { return $('Chọn hàng cần soạn').all()[i]?.json || {}; } };
return $input.all().map((item, i) => {
  const s = src(i);
  const base = { tab: s.tab, row_number: s.row_number, cell_web: s.cell_web, cell_zalo: s.cell_zalo, cell_fb: s.cell_fb, cell_note: s.cell_note };
  // Thinking models (qwen3.5, gemma4) may put their reasoning in <think> tags before the answer.
  const output = String(item.json.output || item.json.text || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  if (item.json.error || !output.trim()) return { json: { ...base, failed: true } };
  let parsed = null;
  const tryParse = (t) => { try { return JSON.parse(t); } catch (e) { return null; } };
  parsed = tryParse(output.replace(/^```(?:json)?\s*|\s*```$/g, ''));
  if (!parsed) { const m = output.match(/\{[\s\S]*"ban_website"[\s\S]*\}/); if (m) parsed = tryParse(m[0]); }
  if (!parsed || !parsed.ban_website) return { json: { ...base, failed: true } };
  return { json: { ...base, failed: false, ban_website: String(parsed.ban_website), ban_zalo: String(parsed.ban_zalo || ''), ban_facebook: String(parsed.ban_facebook || '') } };
});

// One batchUpdate for every row in this run (RAW: text is never parsed as a formula).
const data = [];
for (const { json: r } of $input.all()) {
  if (r.failed) {
    data.push({ range: r.cell_note, values: [['Chưa soạn được bản nháp - vui lòng nhập tay vào cột Bản website (xoá ghi chú này để thử soạn lại)']] });
  } else {
    data.push({ range: r.cell_web, values: [[r.ban_website]] });
    data.push({ range: r.cell_zalo, values: [[r.ban_zalo]] });
    data.push({ range: r.cell_fb, values: [[r.ban_facebook]] });
  }
}
return data.length ? [{ json: { data } }] : [];

